      tags: ['User Management'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const request = findRequestByName(result.items, 'Get users');\n    expect(request).toBeDefined();\n    // Spaces are replaced with underscores for BRU format compatibility\n    expect(request.tags).toEqual(['User_Management']);\n  });\n\n  it('should sanitize tags with dots', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: ['api.v1', 'user.service'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const request = findRequestByName(result.items, 'Get users');\n    expect(request).toBeDefined();\n    // Dots should be replaced with underscores\n    expect(request.tags).toEqual(['api_v1', 'user_service']);\n  });\n\n  it('should sanitize tags with special characters', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: ['API (v1)', 'user-service:v2'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const request = findRequestByName(result.items, 'Get users');\n    expect(request).toBeDefined();\n    // Parentheses, colons, and spaces should be replaced with underscores\n    // 'API (v1)' becomes 'API_v1' (space and parentheses become underscores, collapsed)\n    expect(request.tags).toEqual(['API_v1', 'user-service_v2']);\n  });\n\n  it('should preserve valid tags', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: ['users', 'api-v1', 'user_service'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const request = findRequestByName(result.items, 'Get users');\n    expect(request).toBeDefined();\n    expect(request.tags).toEqual(['users', 'api-v1', 'user_service']);\n  });\n\n  it('should handle empty tags array', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: [],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const request = findRequestByName(result.items, 'Get users');\n    expect(request).toBeDefined();\n    expect(request.tags).toEqual([]);\n  });\n\n  it('should handle missing tags property', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const request = findRequestByName(result.items, 'Get users');\n    expect(request).toBeDefined();\n    expect(request.tags).toEqual([]);\n  });\n\n  it('should remove duplicate tags after sanitization', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: ['User Management', 'User Management', 'user-management'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const request = findRequestByName(result.items, 'Get users');\n    expect(request).toBeDefined();\n    // 'User Management' becomes 'User_Management', which is different from 'user-management'\n    expect(request.tags).toEqual(['User_Management', 'user-management']);\n  });\n\n  it('should filter out tags that become empty after sanitization', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: ['...', 'valid-tag', '---'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const request = findRequestByName(result.items, 'Get users');\n    expect(request).toBeDefined();\n    expect(request.tags).toEqual(['valid-tag']);\n  });\n\n  it('should use sanitized tag names for folder grouping', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: ['User Management'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        },\n        '/posts': {\n          get: {\n            operationId: 'getPosts',\n            summary: 'Get posts',\n            tags: ['User Management'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    // Find the folder created from the tag - spaces replaced with underscores\n    const folder = findFolderByName(result.items, 'User_Management');\n    expect(folder).toBeDefined();\n    expect(folder.name).toBe('User_Management');\n    expect(folder.items).toHaveLength(2);\n  });\n\n  it('should sanitize folder names from tags with dots', () => {\n    const openApiSpec = {\n      openapi: '3.0.0',\n      info: {\n        title: 'Test API',\n        version: '1.0.0'\n      },\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: ['api.v1'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    // Find the folder created from the tag - dots should be replaced\n    const folder = findFolderByName(result.items, 'api_v1');\n    expect(folder).toBeDefined();\n    expect(folder.name).toBe('api_v1');\n  });\n\n  it('should handle utf characters as well', () => {\n    const openApiSpec = {\n      openapi: '3.0.1',\n      info: {\n        title: 'CBC-MODEL3D-API',\n        description: 'POWER BY WARE4U',\n        termsOfService: 'http://swagger.io/terms/',\n        contact: {\n          name: '陈洪',\n          email: 'sendreams@hotmail.com'\n        },\n        license: {\n          name: 'Apache 2.0',\n          url: 'http://springdoc.org'\n        },\n        version: '1.0.0'\n      },\n      tags: [\n        {\n          name: '模型管理',\n          description: '发布和管理3d模型'\n        },\n        {\n          name: '模型集市',\n          description: '模型查询、评价、下单等'\n        }\n      ],\n      paths: {\n        '/users': {\n          get: {\n            operationId: 'getUsers',\n            summary: 'Get users',\n            tags: ['模型管理'],\n            responses: {\n              200: {\n                description: 'Success'\n              }\n            }\n          }\n        }\n      }\n    };\n\n    const result = openApiToBruno(JSON.stringify(openApiSpec));\n    const folder = findFolderByName(result.items, '模型管理');\n    expect(folder).toBeDefined();\n  });\n});\n"],"mappings":";;AAAA,IAAAA,QAAA,GAAAC,OAAA;AACA,IAAAC,eAAA,GAAAC,sBAAA,CAAAF,OAAA;AAAmE,SAAAE,uBAAAC,CAAA,WAAAA,CAAA,IAAAA,CAAA,CAAAC,UAAA,GAAAD,CAAA,KAAAE,OAAA,EAAAF,CAAA;AAEnE;AACA;AACA;AACA;AACA;AACA,MAAMG,iBAAiB,GAAGA,CAACC,KAAK,EAAEC,IAAI,KAAK;EACzC,KAAK,MAAMC,IAAI,IAAIF,KAAK,EAAE;IACxB,IAAIE,IAAI,CAACC,IAAI,KAAK,cAAc,IAAID,IAAI,CAACD,IAAI,KAAKA,IAAI,EAAE;MACtD,OAAOC,IAAI;IACb;IACA,IAAIA,IAAI,CAACC,IAAI,KAAK,QAAQ,IAAID,IAAI,CAACF,KAAK,EAAE;MACxC,MAAMI,KAAK,GAAGL,iBAAiB,CAACG,IAAI,CAACF,KAAK,EAAEC,IAAI,CAAC;MACjD,IAAIG,KAAK,EAAE,OAAOA,KAAK;IACzB;EACF;EACA,OAAOC,SAAS;AAClB,CAAC;;AAED;AACA;AACA;AACA,MAAMC,gBAAgB,GAAGA,CAACN,KAAK,EAAEC,IAAI,KAAK;EACxC,KAAK,MAAMC,IAAI,IAAIF,KAAK,EAAE;IACxB,IAAIE,IAAI,CAACC,IAAI,KAAK,QAAQ,IAA