+{"version":3,"names":["_globals","require","_openapiToBruno","_interopRequireDefault","_swagger2ToBruno","e","__esModule","default","spec","swagger","info","title","host","basePath","schemes","consumes","produces","securityDefinitions","apiKeyAuth","type","name","in","basicAuth","oauth","flow","authorizationUrl","tokenUrl","scopes","read","security","paths","parameters","required","get","summary","operationId","tags","enum","responses","description","schema","properties","id","post","describe","it","c","swagger2ToBruno","expect","toBe","version","uid","toBeDefined","Array","isArray","items","environments","length","variables","toMatchObject","value","root","request","auth","mode","openApiToBruno","yaml","folder","find","i","getPet","pathParam","params","p","statusEntries","filter","enabled","verbose","headers","h","examples","itemUid","response","statusText","createPet","body","upload","fileField","multipartForm","f","noteField","groupBy","petsFolder","noHost","bpOnly","env","circular","definitions","Node","child","$ref","not","toThrow","req"],"sources":["scratch-swagger2.spec.js"],"sourcesContent":["import { describe, it, expect } from '@jest/globals';\nimport openApiToBruno from './src/openapi/openapi-to-bruno';\nimport { swagger2ToBruno } from './src/openapi/swagger2-to-bruno';\n\nconst spec = {\n  swagger: '2.0',\n  info: { title: '  Pet Store  ' },\n  host: 'petstore.example.com',\n  basePath: '/v2',\n  schemes: ['https', 'http'],\n  consumes: ['application/json'],\n  produces: ['application/json'],\n  securityDefinitions: {\n    apiKeyAuth: { type: 'apiKey', name: 'X-API-Key', in: 'header' },\n    basicAuth: { type: 'basic' },\n    oauth: { type: 'oauth2', flow: 'accessCode', authorizationUrl: 'https://a', tokenUrl: 'https://t', scopes: { read: 'r' } }\n  },\n  security: [{ apiKeyAuth: [] }],\n  paths: {\n    '/pets/{petId}': {\n      parameters: [\n        { name: 'petId', in: 'path', required: true, type: 'string' }\n      ],\n      get: {\n        summary: 'Get pet',\n        operationId: 'getPet',\n        tags: ['pets group'],\n        parameters: [\n          { name: 'verbose', in: 'query', type: 'boolean', default: true },\n          { name: 'status', in: 'query', type: 'string', enum: ['available', 'pending', 'sold'] }\n        ],\n        responses: {\n          '200': {\n            description: 'OK',\n            schema: { type: 'object', properties: { id: { type: 'integer' }, name: { type: 'string' } } }\n          },\n          default: { description: 'error' }\n        }\n      },\n      post: {\n        summary: 'Create pet',\n        operationId: 'createPet',\n        tags: ['pets group'],\n        parameters: [\n          { name: 'body', in: 'body', schema: { type: 'object', properties: { name: { type: 'string' } } } }\n        ],\n        security: [],\n        responses: { '201': { description: 'created', schema: { type: 'object', properties: { id: { type: 'integer' } } } } }\n      }\n    },\n    '/upload': {\n      post: {\n        summary: 'Upload',\n        operationId: 'upload',\n        consumes: ['multipart/form-data'],\n        parameters: [\n          { name: 'file', in: 'formData', type: 'file' },\n          { name: 'note', in: 'formData', type: 'string' }\n        ],\n        responses: { '200': { description: 'ok' } }\n      }\n    }\n  }\n};\n\ndescribe('swagger2 smoke', () => {\n  it('converts via named export', () => {\n    const c = swagger2ToBruno(spec);\n    expect(c.name).toBe('Pet Store');\n    expect(c.version).toBe('1');\n    expect(c.uid).toBeDefined();\n    expect(Array.isArray(c.items)).toBe(true);\n    expect(c.environments.length).toBe(2);\n    expect(c.environments[0].name).toBe('Environment 1');\n    expect(c.environments[0].variables[0]).toMatchObject({ name: 'baseUrl', value: 'https://petstore.example.com/v2' });\n    expect(c.environments[1].variables[0].value).toBe('http://petstore.example.com/v2');\n    // global security -> collection root auth apikey\n    expect(c.root.request.auth.mode).toBe('apikey');\n  });\n\n  it('routes through openApiToBruno default export', () => {\n    const c = openApiToBruno(spec);\n    expect(c.name).toBe('Pet Store');\n  });\n\n  it('accepts YAML string via openApiToBruno', () => {\n    const yaml = `swagger: \"2.0\"\\ninfo:\\n  title: YAML API\\nhost: h.com\\nschemes:\\n  - https\\npaths:\\n  /x:\\n    get:\\n      summary: X\\n      responses:\\n        '200':\\n          description: ok`;\n    const c = openApiToBruno(yaml);\n    expect(c.name).toBe('YAML API');\n    expect(c.environments[0].variables[0].value).toBe('https://h.com');\n  });\n\n  it('folder + request structure, auth, enum, examples', () => {\n    const c = swagger2ToBruno(spec);\n    const folder = c.items.find((i) => i.type === 'folder');\n    expect(folder.name).toBe('pets_group');\n    expect(folder.root.request.auth.mode).toBe('inherit');\n    const getPet = folder.items.find((i) => i.name === 'Get pet');\n    // path param merged in\n    const pathParam = getPet.request.params.find((p) => p.type === 'path' && p.name === 'petId');\n    expect(pathParam).toBeDefined();\n    // enum -> multiple entries first enabled\n    const statusEntries = getPet.request.params.filter((p) => p.name === 'status');\n    expect(statusEntries.length).toBe(3);\n    expect(statusEntries[0].enabled).toBe(true);\n    expect(statusEntries[1].enabled).toBe(false);\n    // default boolean coerced to string\n    const verbose = getPet.request.params.find((p) => p.name === 'verbose');\n    expect(verbose.value).toBe('true');\n    // apikey header injected\n    expect(getPet.request.headers.find((h) => h.name === 'X-API-Key' && h.value === '{{apiKey}}')).toBeDefined();\n    // examples\n    expect(Array.isArray(getPet.examples)).toBe(true);\n    expect(getPet.examples[0].name).toBe('200 Response');\n    expect(getPet.examples[0].itemUid).toBe(getPet.uid);\n    expect(getPet.examples[0].response.statusText).toBe('OK');\n    // explicit empty security -> none\n    const createPet = folder.items.find((i) => i.name === 'Create pet');\n    expect(createPet.request.auth.mode).toBe('none');\n    expect(createPet.request.body.mode).toBe('json');\n  });\n\n  it('multipart form body with file field', () => {\n    const c = swagger2ToBruno(spec);\n    const upload = c.items.find((i) => i.name === 'Upload');\n    expect(upload.request.body.mode).toBe('multipartForm');\n    const fileField = upload.request.body.multipartForm.find((f) => f.name === 'file');\n    expect(fileField.type).toBe('file');\n    const noteField = upload.request.body.multipartForm.find((f) => f.name === 'note');\n    expect(noteField.type).toBe('text');\n  });\n\n  it('path-based grouping', () => {\n    const c = swagger2ToBruno(spec, { groupBy: 'path' });\n    const petsFolder = c.items.find((i) => i.name === 'pets');\n    expect(petsFolder).toBeDefined();\n    expect(petsFolder.type).toBe('folder');\n  });\n\n  it('no host -> zero environments; basePath only -> one env', () => {\n    const noHost = { swagger: '2.0', info: { title: 'T' }, paths: {} };\n    expect(swagger2ToBruno(noHost).environments.length).toBe(0);\n    const bpOnly = { swagger: '2.0', info: { title: 'T' }, basePath: '/api', paths: {} };\n    const env = swagger2ToBruno(bpOnly).environments;\n    expect(env.length).toBe(1);\n    expect(env[0].variables[0].value).toBe('/api');\n  });\n\n  it('circular refs do not throw', () => {\n    const circular = {\n      swagger: '2.0',\n      info: { title: 'C' },\n      host: 'h.com',\n      definitions: {\n        Node: { type: 'object', properties: { child: { $ref: '#/definitions/Node' }, name: { type: 'string' } } }\n      },\n      paths: {\n        '/n': {\n          post: {\n            summary: 'N',\n            consumes: ['application/json'],\n            parameters: [{ name: 'body', in: 'body', schema: { $ref: '#/definitions/Node' } }],\n            responses: { '200': { description: 'ok', schema: { $ref: '#/definitions/Node' } } }\n          }\n        }\n      }\n    };\n    expect(() => swagger2ToBruno(circular)).not.toThrow();\n    const c = swagger2ToBruno(circular);\n    const req = c.items.find((i) => i.name === 'N') || c.items[0];\n    expect(req).toBeDefined();\n  });\n\n  it('empty/whitespace title defaults', () => {\n    expect(swagger2ToBruno({ swagger: '2.0', info: { title: '   ' }, paths: {} }).name).toBe('Untitled Collection');\n    expect(swagger2ToBruno({ swagger: '2.0', paths: {} }).name).toBe('Untitled Collection');\n  });\n});\n"],"mappings":";;AAAA,IAAAA,QAAA,GAAAC,OAAA;AACA,IAAAC,eAAA,GAAAC,sBAAA,CAAAF,OAAA;AACA,IAAAG,gBAAA,GAAAH,OAAA;AAAkE,SAAAE,uBAAAE,CAAA,WAAAA,CAAA,IAAAA,CAAA,CAAAC,UAAA,GAAAD,CAAA,KAAAE,OAAA,EAAAF,CAAA;AAElE,MAAMG,IAAI,GAAG;EACXC,OAAO,EAAE,KAAK;EACdC,IAAI,EAAE;IAAEC,KAAK,EAAE;EAAgB,CAAC;EAChCC,IAAI,EAAE,sBAAsB;EAC5BC,QAAQ,EAAE,KAAK;EACfC,OAAO,EAAE,CAAC,OAAO,EAAE,MAAM,CAAC;EAC1BC,QAAQ,EAAE,CAAC,kBAAkB,CAAC;EAC9BC,QAAQ,EAAE,CAAC,kBAAkB,CAAC;EAC9BC,mBAAmB,EAAE;IACnBC,UAAU,EAAE;MAAEC,IAAI,EAAE,QAAQ;MAAEC,IAAI,EAAE,WAAW;MAAEC,EAAE,EAAE;IAAS,CAAC;IAC/DC,SAAS,EAAE;MAAEH,IAAI,EAAE;IAAQ,CAAC;IAC5BI,KAAK,EAAE;MAAEJ,IAAI,EAAE,QAAQ;MAAEK,IAAI,EAAE,YAAY;MAAEC,gBAAgB,EAAE,WAAW;MAAEC,QAAQ,EAAE,WAAW;MAAEC,MAAM,EAAE;QAAEC,IAAI,EAAE;MAAI;IAAE;EAC3H,CAAC;EACDC,QAAQ,EAAE,CAAC;IAAEX,UAAU,EAAE;EAAG,CAAC,CAAC;EAC9BY,KAAK,EAAE;IACL,eAAe,EAAE;MACfC,UAAU,EAAE,CACV;QAAEX,IAAI,EAAE,OAAO;QAAEC,EAAE,EAAE,MAAM;QAAEW,QAAQ,EAAE,IAAI;QAAEb,IAAI,EAAE;MAAS,CAAC,CAC9D;MACDc,GAAG,EAAE;QACHC,OAAO,EAAE,SAAS;QAClBC,WAAW,EAAE,QAAQ;QACrBC,IAAI,EAAE,CAAC,YAAY,CAAC;QACpBL,UAAU,EAAE,CACV;UAAEX,IAAI,EAAE,SAAS;UAAEC,EAAE,EAAE,OAAO;UAAEF,IAAI,EAAE,SAAS;UAAEZ,OAAO,EAAE;QAAK,CAAC,EAChE;UAAEa,IAAI,EAAE,QAAQ;UAAEC,EAAE,EAAE,OAAO;UAAEF,IAAI,EAAE,QAAQ;UAAEkB,IAAI,EAAE,CAAC,WAAW,EAAE,SAAS,EAAE,MAAM;QAAE,CAAC,CACxF;QACDC,SAAS,EAAE;UACT,KAAK,EAAE;YACLC,WAAW,EAAE,IAAI;YACjBC,MAAM,EAAE;cAAErB,IAAI,EAAE,QAAQ;cAAEsB,UAAU,EAAE;gBAAEC,EAAE,EAAE;kBAAEvB,IAAI,EAAE;gBAAU,CAAC;gBAAEC,IAAI,EAAE;kBAAED,IAAI,EAAE;gBAAS;cAAE;YA